-- Initial schema for the TypeScript/NestJS application.
-- Existing db-push databases must be backed up and verified before baselining.
CREATE TABLE "Device" ("id" TEXT NOT NULL,"name" TEXT NOT NULL,"platform" TEXT NOT NULL DEFAULT 'iOS',"tokenHash" TEXT NOT NULL,"active" BOOLEAN NOT NULL DEFAULT true,"lastSeenAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Device_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Campaign" ("id" TEXT NOT NULL,"name" TEXT NOT NULL,"messageSet" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'DRAFT',"batchSize" INTEGER NOT NULL DEFAULT 20,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Campaign_pkey" PRIMARY KEY ("id"));
CREATE TABLE "CampaignRecipient" ("id" TEXT NOT NULL,"campaignId" TEXT NOT NULL,"phone" TEXT NOT NULL,"consented" BOOLEAN NOT NULL DEFAULT false,"consentAt" TIMESTAMP(3),"status" TEXT NOT NULL DEFAULT 'PENDING',"validation" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "CampaignRecipient_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Suppression" ("phone" TEXT NOT NULL,"reason" TEXT NOT NULL DEFAULT 'STOP',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Suppression_pkey" PRIMARY KEY ("phone"));
CREATE TABLE "CampaignDevice" ("campaignId" TEXT NOT NULL,"deviceId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "CampaignDevice_pkey" PRIMARY KEY ("campaignId","deviceId"));
CREATE TABLE "ValidationApiKey" ("id" TEXT NOT NULL,"label" TEXT NOT NULL,"encryptedKey" TEXT NOT NULL,"iv" TEXT NOT NULL,"authTag" TEXT NOT NULL,"fingerprint" TEXT NOT NULL,"lastFour" TEXT NOT NULL,"enabled" BOOLEAN NOT NULL DEFAULT true,"status" TEXT NOT NULL DEFAULT 'READY',"requestCount" INTEGER NOT NULL DEFAULT 0,"failureCount" INTEGER NOT NULL DEFAULT 0,"lastUsedAt" TIMESTAMP(3),"lastError" TEXT,"cooldownUntil" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "ValidationApiKey_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ValidationKeyRotation" ("id" TEXT NOT NULL DEFAULT 'global',"sequence" BIGINT NOT NULL DEFAULT 0,CONSTRAINT "ValidationKeyRotation_pkey" PRIMARY KEY ("id"));
CREATE TABLE "CampaignBatch" ("id" TEXT NOT NULL,"campaignId" TEXT NOT NULL,"deviceId" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'PENDING_APPROVAL',"approvedAt" TIMESTAMP(3),"startedAt" TIMESTAMP(3),"completedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "CampaignBatch_pkey" PRIMARY KEY ("id"));
CREATE TABLE "BatchRecipient" ("id" TEXT NOT NULL,"batchId" TEXT NOT NULL,"recipientId" TEXT NOT NULL,"message" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'QUEUED',"attemptedAt" TIMESTAMP(3),"sentAt" TIMESTAMP(3),"error" TEXT,"providerMessageId" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "BatchRecipient_pkey" PRIMARY KEY ("id"));
CREATE TABLE "AutoReplySettings" ("id" TEXT NOT NULL DEFAULT 'global',"enabled" BOOLEAN NOT NULL DEFAULT false,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "AutoReplySettings_pkey" PRIMARY KEY ("id"));
CREATE TABLE "DeviceAutoReplySettings" ("id" TEXT NOT NULL,"deviceId" TEXT NOT NULL,"enabled" BOOLEAN NOT NULL DEFAULT true,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "DeviceAutoReplySettings_pkey" PRIMARY KEY ("id"));
CREATE TABLE "AutoReplyRule" ("id" TEXT NOT NULL,"scope" TEXT NOT NULL DEFAULT 'GLOBAL',"deviceId" TEXT,"name" TEXT NOT NULL,"keyword" TEXT,"message" TEXT NOT NULL,"enabled" BOOLEAN NOT NULL DEFAULT true,"cooldownMinutes" INTEGER NOT NULL DEFAULT 1440,"priority" INTEGER NOT NULL DEFAULT 0,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "AutoReplyRule_pkey" PRIMARY KEY ("id"));
CREATE TABLE "AutoReplyEvent" ("id" TEXT NOT NULL,"deviceId" TEXT NOT NULL,"externalMessageId" TEXT NOT NULL,"phone" TEXT NOT NULL,"incomingText" TEXT NOT NULL,"replyText" TEXT,"status" TEXT NOT NULL DEFAULT 'RECEIVED',"ruleId" TEXT,"error" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"reportedAt" TIMESTAMP(3),CONSTRAINT "AutoReplyEvent_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Device_tokenHash_key" ON "Device"("tokenHash");
CREATE INDEX "Device_active_lastSeenAt_idx" ON "Device"("active","lastSeenAt");
CREATE INDEX "Campaign_status_createdAt_idx" ON "Campaign"("status","createdAt");
CREATE UNIQUE INDEX "CampaignRecipient_campaignId_phone_key" ON "CampaignRecipient"("campaignId","phone");
CREATE INDEX "CampaignRecipient_campaignId_status_idx" ON "CampaignRecipient"("campaignId","status");
CREATE INDEX "CampaignRecipient_phone_idx" ON "CampaignRecipient"("phone");
CREATE UNIQUE INDEX "ValidationApiKey_fingerprint_key" ON "ValidationApiKey"("fingerprint");
CREATE INDEX "ValidationApiKey_enabled_cooldownUntil_createdAt_idx" ON "ValidationApiKey"("enabled","cooldownUntil","createdAt");
CREATE INDEX "CampaignBatch_deviceId_status_createdAt_idx" ON "CampaignBatch"("deviceId","status","createdAt");
CREATE INDEX "CampaignBatch_campaignId_status_idx" ON "CampaignBatch"("campaignId","status");
CREATE UNIQUE INDEX "BatchRecipient_batchId_recipientId_key" ON "BatchRecipient"("batchId","recipientId");
CREATE INDEX "BatchRecipient_batchId_status_idx" ON "BatchRecipient"("batchId","status");
CREATE UNIQUE INDEX "DeviceAutoReplySettings_deviceId_key" ON "DeviceAutoReplySettings"("deviceId");
CREATE INDEX "AutoReplyRule_scope_deviceId_enabled_priority_idx" ON "AutoReplyRule"("scope","deviceId","enabled","priority");
CREATE UNIQUE INDEX "AutoReplyEvent_deviceId_externalMessageId_key" ON "AutoReplyEvent"("deviceId","externalMessageId");
CREATE INDEX "AutoReplyEvent_phone_createdAt_idx" ON "AutoReplyEvent"("phone","createdAt");
CREATE INDEX "AutoReplyEvent_deviceId_createdAt_idx" ON "AutoReplyEvent"("deviceId","createdAt");
CREATE INDEX "AutoReplyEvent_status_createdAt_idx" ON "AutoReplyEvent"("status","createdAt");
ALTER TABLE "CampaignRecipient" ADD CONSTRAINT "CampaignRecipient_campaignId_fkey" FOREIGN KEY ("campaignId") REFERENCES "Campaign"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "CampaignDevice" ADD CONSTRAINT "CampaignDevice_campaignId_fkey" FOREIGN KEY ("campaignId") REFERENCES "Campaign"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "CampaignDevice" ADD CONSTRAINT "CampaignDevice_deviceId_fkey" FOREIGN KEY ("deviceId") REFERENCES "Device"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "CampaignBatch" ADD CONSTRAINT "CampaignBatch_campaignId_fkey" FOREIGN KEY ("campaignId") REFERENCES "Campaign"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "CampaignBatch" ADD CONSTRAINT "CampaignBatch_deviceId_fkey" FOREIGN KEY ("deviceId") REFERENCES "Device"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "BatchRecipient" ADD CONSTRAINT "BatchRecipient_batchId_fkey" FOREIGN KEY ("batchId") REFERENCES "CampaignBatch"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "BatchRecipient" ADD CONSTRAINT "BatchRecipient_recipientId_fkey" FOREIGN KEY ("recipientId") REFERENCES "CampaignRecipient"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "DeviceAutoReplySettings" ADD CONSTRAINT "DeviceAutoReplySettings_deviceId_fkey" FOREIGN KEY ("deviceId") REFERENCES "Device"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "AutoReplyRule" ADD CONSTRAINT "AutoReplyRule_deviceId_fkey" FOREIGN KEY ("deviceId") REFERENCES "Device"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "AutoReplyEvent" ADD CONSTRAINT "AutoReplyEvent_deviceId_fkey" FOREIGN KEY ("deviceId") REFERENCES "Device"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "AutoReplyEvent" ADD CONSTRAINT "AutoReplyEvent_ruleId_fkey" FOREIGN KEY ("ruleId") REFERENCES "AutoReplyRule"("id") ON DELETE SET NULL ON UPDATE CASCADE;
